CREATE TYPE public.app_role AS ENUM ('super_admin','admin','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', kyc_status text NOT NULL DEFAULT 'not_started' CHECK (kyc_status IN ('not_started','pending','verified','rejected')), balance numeric(18,2) NOT NULL DEFAULT 0 CHECK (balance >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
CREATE UNIQUE INDEX one_super_admin ON public.user_roles(role) WHERE role='super_admin';
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id,'admin') OR public.has_role(_user_id,'super_admin') $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE TABLE public.traders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, handle text NOT NULL UNIQUE, strategy text NOT NULL, risk_level text NOT NULL CHECK (risk_level IN ('Low','Moderate','High')), roi_12m numeric(8,2) NOT NULL DEFAULT 0, followers integer NOT NULL DEFAULT 0, aum numeric(18,2) NOT NULL DEFAULT 0, featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT ON public.traders TO anon, authenticated; GRANT ALL ON public.traders TO service_role;
ALTER TABLE public.traders ENABLE ROW LEVEL SECURITY;
CREATE POLICY traders_public ON public.traders FOR SELECT TO anon, authenticated USING (deleted_at IS NULL);
CREATE TABLE public.deposits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id), asset text NOT NULL CHECK (asset IN ('USDT','BTC','ETH')), network text NOT NULL, amount numeric(18,2) NOT NULL CHECK (amount > 0), tx_reference text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','confirmed','rejected')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT, INSERT ON public.deposits TO authenticated; GRANT ALL ON public.deposits TO service_role;
ALTER TABLE public.deposits ENABLE ROW LEVEL SECURITY;
CREATE POLICY deposits_read ON public.deposits FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY deposits_create ON public.deposits FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND status='pending');
CREATE TABLE public.withdrawals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id), asset text NOT NULL DEFAULT 'USDT', network text NOT NULL, destination text NOT NULL, amount numeric(18,2) NOT NULL CHECK (amount > 0), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','completed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT ON public.withdrawals TO authenticated; GRANT ALL ON public.withdrawals TO service_role;
ALTER TABLE public.withdrawals ENABLE ROW LEVEL SECURITY;
CREATE POLICY withdrawals_read ON public.withdrawals FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE TABLE public.copy_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id), trader_id uuid NOT NULL REFERENCES public.traders(id), amount numeric(18,2) NOT NULL CHECK (amount > 0), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','stopped')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT ON public.copy_allocations TO authenticated; GRANT ALL ON public.copy_allocations TO service_role;
ALTER TABLE public.copy_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY allocations_read ON public.copy_allocations FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE TABLE public.support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id), subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','resolved')), reply text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT, INSERT ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY tickets_read ON public.support_tickets FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE POLICY tickets_create ON public.support_tickets FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND status='open' AND reply IS NULL);
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id), title text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
GRANT SELECT, UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.activity_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id), action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_logs TO authenticated; GRANT ALL ON public.activity_logs TO service_role;
ALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.activity_logs FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_staff(auth.uid()));
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES auth.users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_staff_read ON public.audit_logs FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profiles_touch BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER traders_touch BEFORE UPDATE ON public.traders FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER deposits_touch BEFORE UPDATE ON public.deposits FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER withdrawals_touch BEFORE UPDATE ON public.withdrawals FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER allocations_touch BEFORE UPDATE ON public.copy_allocations FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER tickets_touch BEFORE UPDATE ON public.support_tickets FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER notifications_touch BEFORE UPDATE ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE OR REPLACE FUNCTION public.on_account_created() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_account_created();
CREATE OR REPLACE FUNCTION public.request_withdrawal(_amount numeric,_network text,_destination text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF _amount <= 0 OR length(trim(_destination)) < 8 OR length(trim(_network)) < 2 THEN RAISE EXCEPTION 'Invalid withdrawal'; END IF; UPDATE public.profiles SET balance=balance-_amount WHERE id=auth.uid() AND balance>=_amount AND kyc_status='verified'; IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient available balance or verification incomplete'; END IF; INSERT INTO public.withdrawals(user_id,network,destination,amount) VALUES(auth.uid(),_network,_destination,_amount) RETURNING id INTO _id; INSERT INTO public.activity_logs(user_id,action,details) VALUES(auth.uid(),'withdrawal_requested',jsonb_build_object('withdrawal_id',_id)); RETURN _id; END $$;
CREATE OR REPLACE FUNCTION public.allocate_copy(_trader_id uuid,_amount numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; IF _amount <= 0 OR NOT EXISTS(SELECT 1 FROM public.traders WHERE id=_trader_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Invalid allocation'; END IF; UPDATE public.profiles SET balance=balance-_amount WHERE id=auth.uid() AND balance>=_amount AND kyc_status='verified'; IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient available balance or verification incomplete'; END IF; INSERT INTO public.copy_allocations(user_id,trader_id,amount) VALUES(auth.uid(),_trader_id,_amount) RETURNING id INTO _id; INSERT INTO public.activity_logs(user_id,action,details) VALUES(auth.uid(),'copy_started',jsonb_build_object('allocation_id',_id)); RETURN _id; END $$;
CREATE OR REPLACE FUNCTION public.set_copy_status(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _row public.copy_allocations%ROWTYPE; BEGIN IF _status NOT IN ('paused','active','stopped') THEN RAISE EXCEPTION 'Invalid status'; END IF; SELECT * INTO _row FROM public.copy_allocations WHERE id=_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR _row.status='stopped' THEN RAISE EXCEPTION 'Allocation unavailable'; END IF; UPDATE public.copy_allocations SET status=_status WHERE id=_id; IF _status='stopped' THEN UPDATE public.profiles SET balance=balance+_row.amount WHERE id=auth.uid(); END IF; END $$;
CREATE OR REPLACE FUNCTION public.review_deposit(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _row public.deposits%ROWTYPE; BEGIN IF NOT public.is_staff(auth.uid()) OR _status NOT IN ('confirmed','rejected') THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT * INTO _row FROM public.deposits WHERE id=_id FOR UPDATE; IF NOT FOUND OR _row.status<>'pending' THEN RAISE EXCEPTION 'Deposit unavailable'; END IF; UPDATE public.deposits SET status=_status WHERE id=_id; IF _status='confirmed' THEN UPDATE public.profiles SET balance=balance+_row.amount WHERE id=_row.user_id; END IF; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id) VALUES(auth.uid(),'deposit_'||_status,'deposit',_id); INSERT INTO public.notifications(user_id,title,message) VALUES(_row.user_id,'Deposit '||_status,'Your deposit review is complete.'); END $$;
CREATE OR REPLACE FUNCTION public.review_withdrawal(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _row public.withdrawals%ROWTYPE; BEGIN IF NOT public.is_staff(auth.uid()) OR _status NOT IN ('completed','rejected') THEN RAISE EXCEPTION 'Not allowed'; END IF; SELECT * INTO _row FROM public.withdrawals WHERE id=_id FOR UPDATE; IF NOT FOUND OR _row.status<>'pending' THEN RAISE EXCEPTION 'Withdrawal unavailable'; END IF; UPDATE public.withdrawals SET status=_status WHERE id=_id; IF _status='rejected' THEN UPDATE public.profiles SET balance=balance+_row.amount WHERE id=_row.user_id; END IF; INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id) VALUES(auth.uid(),'withdrawal_'||_status,'withdrawal',_id); INSERT INTO public.notifications(user_id,title,message) VALUES(_row.user_id,'Withdrawal '||_status,'Your withdrawal review is complete.'); END $$;
REVOKE ALL ON FUNCTION public.request_withdrawal(numeric,text,text), public.allocate_copy(uuid,numeric), public.set_copy_status(uuid,text), public.review_deposit(uuid,text), public.review_withdrawal(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_withdrawal(numeric,text,text), public.allocate_copy(uuid,numeric), public.set_copy_status(uuid,text), public.review_deposit(uuid,text), public.review_withdrawal(uuid,text), public.has_role(uuid,public.app_role), public.is_staff(uuid) TO authenticated;